import './header.css';
import React, { useEffect, useState } from 'react';
export function Header(){
    const [showMenu, setShowMenu]=useState(false);
    const [activeNav,setActiveNav]=useState('#home');

    useEffect(() => {
        const updateHeader = () => {
            document.querySelector('.header')?.classList.toggle('scroll-header', window.scrollY >= 40);
        };
        window.addEventListener('scroll', updateHeader, { passive: true });
        updateHeader();
        return () => window.removeEventListener('scroll', updateHeader);
    }, []);

    const closeMenu = (section) => {
        setActiveNav(section);
        setShowMenu(false);
    };

    return(
        <div>
            <header className="header">
                <nav className="nav container">
                    <a href='#home' className='nav__logo' onClick={() => closeMenu('#home')}>Nikitha</a>
                    <div id="site-navigation" className={showMenu ? "nav__menu show-menu":"nav__menu"}>
                        <ul className="nav__list grid">
                            <li className="nav__item">
                                <a href="#home" onClick={()=>closeMenu('#home')}className={activeNav==="#home"?'nav__link active-link':'nav__link'}>
                                    <i className="uil uil-estate nav__icon"></i>Home
                                </a>
                            </li>
                            <li className="nav__item">
                                <a href="#about" onClick={()=>closeMenu('#about')}className={activeNav==="#about"?'nav__link active-link':'nav__link'}>
                                    <i className="uil uil-user nav__icon"></i>About
                                </a>
                            </li>
                            <li className="nav__item">
                                <a href="#skills" onClick={()=>closeMenu('#skills')}className={activeNav==="#skills"?'nav__link active-link':'nav__link'}>
                                    <i className="uil uil-file-alt nav__icon"></i>Skills
                                </a>
                            </li>
                            <li className="nav__item">
                                <a href="#internships" onClick={()=>closeMenu('#internships')}className={activeNav==="#internships"?'nav__link active-link':'nav__link'}>
                                    <i className="uil uil-clipboard nav__icon"></i>Internships
                                </a>
                            </li>
                            <li className="nav__item">
                                <a href="#projects" onClick={()=>closeMenu('#projects')}className={activeNav==="#projects"?'nav__link active-link':'nav__link'}>
                                    <i className="uil uil-file-shield-alt nav__icon"></i>Projects
                                </a>
                            </li>
                            <li className="nav__item">
                                <a href="#education" onClick={()=>closeMenu('#education')}className={activeNav==="#education"?'nav__link active-link':'nav__link'}>
                                    <i className="uil uil-graduation-cap nav__icon"></i>Education
                                </a>
                            </li>
                            <li className="nav__item">
                                <a href="#contact" onClick={()=>closeMenu('#contact')}className={activeNav==="#contact"?'nav__link active-link':'nav__link'}>
                                    <i className="uil uil-message nav__icon"></i>Contact
                                </a>
                            </li>
                        </ul>
                        <button type="button" className='nav__close' aria-label="Close navigation menu" onClick={() => setShowMenu(false)}>
                            <i className='uil uil-times' aria-hidden="true"></i>
                        </button>
                    </div>
                    <button type="button" className='nav_toggle' aria-label={showMenu ? "Close navigation menu" : "Open navigation menu"} aria-expanded={showMenu} aria-controls="site-navigation" onClick={() => setShowMenu(!showMenu)}>
                        <i className="uil uil-apps" aria-hidden="true"></i>
                    </button>
                </nav>
            </header>
        </div>
    )
}
